public class Solution {
  /**
   * accessOrder=true 的 LinkedHashMap：get 命中会把条目移到最近使用端，
   * 过期判断只在"访问该 key"与"需要腾容量时看 LRU 尾"两处发生 —— 纯懒式回收，
   * 因此不存在全表扫描，每次操作摊销 O(1)。
   * 条目值里存 lastTouch；ttlMillis <= 0 表示永不过期。
   */
  public static int[] replayEvictions(int capacity, int ttlMillis, int[] keys, int[] times) {
    if (capacity < 1) throw new IllegalArgumentException("capacity must be >= 1");
    java.util.LinkedHashMap<Integer, int[]> cache =
        new java.util.LinkedHashMap<Integer, int[]>(16, 0.75f, true);
    java.util.List<Integer> evicted = new java.util.ArrayList<>();
    for (int op = 0; op < keys.length; op++) {
      int key = keys[op];
      long now = times[op];
      int[] meta = cache.get(key);                     // 命中即提升 recency
      if (meta != null) {
        if (ttlMillis <= 0 || now - meta[0] < ttlMillis) {
          meta[0] = (int) now;                        // 读续期：recency 与 TTL 一起更新
          continue;
        }
        cache.remove(key);                            // 过期：静默丢弃，不算驱逐
      }
      cache.put(key, new int[] { (int) now });
      while (cache.size() > capacity) {
        java.util.Iterator<Integer> eldestIt = cache.keySet().iterator();
        Integer eldest = eldestIt.next();             // accessOrder=true 的头 = 最久未使用
        eldestIt.remove();
        evicted.add(eldest);
      }
    }
    int[] out = new int[evicted.size()];
    for (int i = 0; i < out.length; i++) out[i] = evicted.get(i);
    return out;
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：每次操作前全表扫描，把所有过期条目都当成"驱逐"上报。
  // 复杂度退化为 O(capacity) 每次操作，并且把"过期静默丢弃"错误地算进驱逐序列。
  public static int[] replayEvictions(int capacity, int ttlMillis, int[] keys, int[] times) {
    if (capacity < 1) throw new IllegalArgumentException("capacity must be >= 1");
    java.util.LinkedHashMap<Integer, Integer> cache =
        new java.util.LinkedHashMap<Integer, Integer>(16, 0.75f, true);
    java.util.List<Integer> evicted = new java.util.ArrayList<>();
    for (int op = 0; op < keys.length; op++) {
      long now = times[op];
      java.util.Iterator<java.util.Map.Entry<Integer, Integer>> sweep = cache.entrySet().iterator();
      while (sweep.hasNext()) {
        java.util.Map.Entry<Integer, Integer> e = sweep.next();
        if (ttlMillis > 0 && now - e.getValue() >= ttlMillis) {
          sweep.remove();
          evicted.add(e.getKey());
        }
      }
      Integer last = cache.get(keys[op]);
      cache.put(keys[op], (int) now);
      if (last != null) continue;
      while (cache.size() > capacity) {
        Integer eldest = cache.keySet().iterator().next();
        evicted.add(eldest);
        cache.remove(eldest);
      }
    }
    int[] out = new int[evicted.size()];
    for (int i = 0; i < out.length; i++) out[i] = evicted.get(i);
    return out;
  }
}
